def dispatch(registry: dict, call: dict):
    """Look up call['name'] in registry and call it with call['args']."""
    name = call["name"]
    if name not in registry:
        raise ValueError(f"unknown tool '{name}'")
    return registry[name](**call.get("args", {}))

registry = {"add": lambda a, b: a + b, "mul": lambda a, b: a * b}
print(dispatch(registry, {"name": "add", "args": {"a": 2, "b": 3}}))
